from __future__ import annotations

from datetime import datetime, timezone
from typing import Any, Callable, Dict, List

try:
    from . import core_access_service as access_svc
    from . import core_pass_service as pass_svc
    from . import core_public_pass_projection_store as projection_store
except ImportError:  # pragma: no cover - supports direct script execution.
    import core_access_service as access_svc
    import core_pass_service as pass_svc
    import core_public_pass_projection_store as projection_store


SCHEMA_VERSION = "liveuin-public-pass-gateway-v1"
PHASE = "phase-next-public-pass-read-gateway"
CANONICAL_OWNER = "LiveUIN Core/Trust/Ops"
SURFACE = "api.liveuin.com read-only Pass gateway"
READ_SCOPE = "liveuin_pass:read"
PUBLIC_VIEWER_SCOPE = "public"
PRIVATE_FRAGMENTS = ("s3://", "gs://", "private/liveuin", "raw_storage_uri", "internal reviewer note")
DEMO_PASS_CASE_ID = "PASS-NUS-2026-888"
PUBLIC_PASS_ACTION = "pass.public_projection.read"
PUBLIC_PASS_PURPOSE = "public_pass_projection"
PUBLIC_PASS_RECIPIENT = "public_pass_viewer"
PUBLIC_PASS_DISCLOSURE_MODEL = "least_privilege_public_pass_projection"
PUBLIC_PASS_REQUIRED_VISIBILITY = {"public_result", "verification_summary", "proof_summary", "movein_summary"}
FORBIDDEN_DIRECT_STORE_ROOTS = ("/srv/liveuin",)
PROJECTION_MAX_AGE_SECONDS = 24 * 60 * 60


def _clean_id(value: Any, max_length: int = 96) -> str:
    return "".join(ch for ch in str(value or "").strip() if ch.isalnum() or ch in "_.:-")[:max_length]


def _as_dict(value: Any) -> Dict[str, Any]:
    return value if isinstance(value, dict) else {}


def _as_list(value: Any) -> List[Any]:
    return value if isinstance(value, list) else []


def _safe_str(value: Any, fallback: str = "") -> str:
    text = str(value or "").strip()
    return text or fallback


def _parse_dt(value: Any) -> datetime | None:
    text = _safe_str(value)
    if not text:
        return None
    try:
        return datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError:
        return None


def _workspace_brand(workspace_id: str) -> Dict[str, str]:
    slug = _clean_id(workspace_id).lower()
    if slug in {"laijuzhu", "wsp_laijuzhu"}:
        return {
            "slug": "laijuzhu",
            "local": "来居住",
            "latin": "LAIJUZHU",
            "program_label": "来居住 (LAIJUZHU)",
            "sub_label": "来居住安心通行证",
        }
    display = slug.upper() or "LIVEUIN"
    return {
        "slug": slug or "liveuin",
        "local": display,
        "latin": display,
        "program_label": display,
        "sub_label": "LiveUIN credential verification",
    }


def _minimal_verification_profiles(payload: Dict[str, Any]) -> List[Dict[str, Any]]:
    profiles = _as_list(_as_dict(_as_dict(payload.get("verification")).get("summary")).get("profiles"))
    if not profiles:
        profiles = _as_list(_as_dict(payload.get("verification")).get("profiles"))
    safe_profiles: List[Dict[str, Any]] = []
    for profile in profiles:
        profile_dict = _as_dict(profile)
        publish_gate = _as_dict(profile_dict.get("publish_gate"))
        safe_profiles.append(
            {
                "verification_state": _safe_str(profile_dict.get("verification_state")),
                "verification_level": _safe_str(profile_dict.get("verification_level")),
                "trust_badge": _safe_str(profile_dict.get("trust_badge")),
                "evidence_count": int(profile_dict.get("evidence_count") or len(_as_list(profile_dict.get("evidence"))) or 0),
                "updated_at": _safe_str(profile_dict.get("updated_at")),
                "publish_gate": {
                    "status": _safe_str(publish_gate.get("status")),
                    "trust_badge": _safe_str(publish_gate.get("trust_badge")),
                },
            }
        )
    return safe_profiles


def _derive_public_level(payload: Dict[str, Any], profiles: List[Dict[str, Any]]) -> Dict[str, Any]:
    verification_summary = _as_dict(_as_dict(payload.get("verification")).get("summary"))
    movein_summary = _as_dict(_as_dict(payload.get("movein")).get("summary"))
    latest_card = _as_dict(_as_dict(payload.get("movein")).get("latest_card"))
    proof = _as_dict((_as_list(payload.get("proof")) or [{}])[0])
    checklist = {str(item.get("key") or ""): _safe_str(item.get("state")) for item in _as_list(latest_card.get("checklist")) if isinstance(item, dict)}
    docs = any(int(_as_dict(profile).get("evidence_count") or 0) > 0 for profile in profiles)
    identity = int(verification_summary.get("verified_count") or 0) > 0 or checklist.get("identity_verification") == "confirmed"
    room = _safe_str(proof.get("status")).lower() == "verified" or checklist.get("room_proof") == "confirmed"
    onsite = checklist.get("handover_time") == "confirmed" and checklist.get("local_contact") == "confirmed"
    fully_verified = (
        docs
        and identity
        and room
        and onsite
        and checklist.get("first_72h") == "confirmed"
        and int(movein_summary.get("blocker_count") or 0) == 0
    )
    if fully_verified:
        return {"code": "V5", "title": "Fully Verified", "index": 5}
    if onsite:
        return {"code": "V4", "title": "Certified", "index": 4}
    if room:
        return {"code": "V3", "title": "Assured", "index": 3}
    if identity:
        return {"code": "V2", "title": "Trusted", "index": 2}
    return {"code": "V1", "title": "Verified", "index": 1}


def _derive_public_status(payload: Dict[str, Any], profiles: List[Dict[str, Any]]) -> Dict[str, Any]:
    verification_summary = _as_dict(_as_dict(payload.get("verification")).get("summary"))
    latest_card = _as_dict(_as_dict(payload.get("movein")).get("latest_card"))
    valid_until = _safe_str(
        latest_card.get("support_window_ends_at")
        or latest_card.get("handover_at")
        or _as_dict(_as_dict(payload.get("movein")).get("summary")).get("handover_at")
    )
    states = {_safe_str(_as_dict(profile).get("verification_state")).lower() for profile in profiles}
    publish_gate = _safe_str(latest_card.get("publish_gate")).lower()
    valid_date = _parse_dt(valid_until)
    now = datetime.now(timezone.utc)
    if not payload or payload.get("ok") is False:
        return {"key": "invalid", "title": "Credential Not Verified", "subtitle": "Invalid or missing credential", "valid_until": valid_until}
    if "suspended" in states:
        return {"key": "suspended", "title": "Credential Suspended", "subtitle": "Temporarily paused pending review", "valid_until": valid_until}
    if "expired" in states:
        return {"key": "expired", "title": "Credential Expired", "subtitle": "Credential no longer valid", "valid_until": valid_until}
    if "rejected" in states or publish_gate == "blocked" or int(verification_summary.get("blocked_count") or 0) > 0:
        return {"key": "revoked", "title": "Credential Revoked", "subtitle": "Credential disabled by trust owner", "valid_until": valid_until}
    if valid_date and valid_date < now:
        return {"key": "expired", "title": "Credential Expired", "subtitle": "Credential no longer valid", "valid_until": valid_until}
    if valid_date and (valid_date - now).total_seconds() <= 14 * 24 * 60 * 60:
        return {"key": "expiring", "title": "Credential Expiring Soon", "subtitle": "Active but renewal needed", "valid_until": valid_until}
    return {"key": "valid", "title": "Credential Verified", "subtitle": "Active", "valid_until": valid_until}


def _contains_private_fragment(value: Any) -> bool:
    encoded = str(value).lower()
    return any(fragment in encoded for fragment in PRIVATE_FRAGMENTS)


def _projection_store_root_blocker() -> str:
    for key in (
        "LIVEUIN_PUBLIC_PASS_PROJECTION_DATA_DIR",
        "LIVEUIN_PUBLIC_PASS_PROJECTION_SQLITE_PATH",
    ):
        value = _safe_str(__import__("os").environ.get(key))
        if not value:
            continue
        for forbidden in FORBIDDEN_DIRECT_STORE_ROOTS:
            if value == forbidden or value.startswith(forbidden + "/"):
                return "public_pass_private_store_root_forbidden:" + key
    return ""


def _projection_freshness_blocker(record: Dict[str, Any]) -> str:
    updated_at = int(record.get("updated_at") or 0)
    if not updated_at:
        return "public_pass_projection_missing_updated_at"
    if int(datetime.now(timezone.utc).timestamp()) - updated_at > PROJECTION_MAX_AGE_SECONDS:
        return "public_pass_projection_stale"
    return ""


def _grant_projection_blocker(grant: Dict[str, Any], *, case_id: str, purpose: str, recipient: str) -> str:
    conditions = _as_dict(grant.get("conditions"))
    grant_case_id = _clean_id(grant.get("case_id"))
    if grant_case_id != _clean_id(case_id):
        return "participant_grant_case_binding_mismatch"
    if _safe_str(conditions.get("withdrawal_state"), "not_withdrawn") != "not_withdrawn":
        return "participant_grant_withdrawn"
    if not _safe_str(conditions.get("consent_version")):
        return "participant_grant_consent_version_required"
    if _safe_str(conditions.get("purpose")) != purpose:
        return "participant_grant_purpose_mismatch"
    recipients = {str(item) for item in _as_list(conditions.get("recipients"))}
    if recipient not in recipients:
        return "participant_grant_recipient_forbidden"
    if _safe_str(conditions.get("disclosure_model")) != PUBLIC_PASS_DISCLOSURE_MODEL:
        return "participant_grant_disclosure_model_mismatch"
    visibility = {str(item) for item in _as_list(conditions.get("visibility_fields"))}
    if not PUBLIC_PASS_REQUIRED_VISIBILITY.issubset(visibility):
        return "participant_grant_visibility_fields_incomplete"
    return ""


def _projection_grant(
    *,
    workspace_id: str,
    case_id: str,
    grant_id: str = "",
    participant_id: str = "",
    purpose: str = PUBLIC_PASS_PURPOSE,
    recipient: str = PUBLIC_PASS_RECIPIENT,
) -> Dict[str, Any]:
    if not grant_id and not participant_id:
        return {"ok": False, "detail": "participant_grant_required", "status_code": 403}
    evaluated = access_svc.evaluate_participant_grant(
        {
            "workspace_id": workspace_id,
            "case_id": case_id,
            "grant_id": grant_id,
            "participant_id": participant_id,
            "action": PUBLIC_PASS_ACTION,
            "resource": {"type": "pass", "id": case_id},
        },
        {"ip": "", "user_agent": "public-pass-gateway", "referer": ""},
    )
    if evaluated.get("ok") is False:
        return evaluated
    if evaluated.get("allowed") is not True:
        return {"ok": False, "detail": evaluated.get("reason") or "participant_grant_denied", "status_code": 403, "grant_evaluation": evaluated}
    grant = _as_dict(evaluated.get("participant_grant"))
    blocker = _grant_projection_blocker(grant, case_id=case_id, purpose=purpose, recipient=recipient)
    if blocker:
        return {"ok": False, "detail": blocker, "status_code": 403, "grant_evaluation": evaluated}
    return {"ok": True, "participant_grant": grant, "grant_evaluation": evaluated}


def _public_display_overrides(case_id: str, workspace_id: str) -> Dict[str, Any]:
    if _clean_id(case_id) == DEMO_PASS_CASE_ID and _clean_id(workspace_id).lower() in {"laijuzhu", "wsp_laijuzhu"}:
        return {
            "verification_id": "LJZ202505150001",
            "valid_until_en": "30 JUN 2026",
            "valid_until_local": "2026年6月30日",
            "last_checked_en": "15 MAY 2025 10:24",
            "last_checked_local": "2026年5月15日 10:24",
            "scan_location_en": "Singapore",
            "scan_location_local": "新加坡",
        }
    return {}


def _public_projection(response: Dict[str, Any]) -> Dict[str, Any]:
    response = response if isinstance(response, dict) else {}
    workspace_id = _safe_str(response.get("workspace_id"), pass_svc.DEFAULT_WORKSPACE_ID)
    case_id = _safe_str(response.get("case_id") or response.get("pass_id"))
    metadata = _as_dict(response.get("metadata"))
    verification = _as_dict(response.get("verification"))
    verification_summary = _as_dict(verification.get("summary"))
    movein = _as_dict(response.get("movein"))
    latest_card = _as_dict(movein.get("latest_card"))
    movein_summary = _as_dict(movein.get("summary"))
    proof = _as_dict((_as_list(response.get("proof")) or [{}])[0])
    brand = _workspace_brand(workspace_id)
    profiles = _minimal_verification_profiles(response)
    public_level = _derive_public_level(response, profiles)
    public_status = _derive_public_status(response, profiles)
    safe_checklist = [
        {"key": _safe_str(item.get("key")), "state": _safe_str(item.get("state"))}
        for item in _as_list(latest_card.get("checklist"))
        if isinstance(item, dict) and _safe_str(item.get("key"))
    ]
    projection = {
        "ok": response.get("ok") is not False,
        "case_id": case_id,
        "pass_id": _safe_str(response.get("pass_id") or case_id),
        "workspace_id": workspace_id,
        "schema_version": response.get("schema_version") or pass_svc.SCHEMA_VERSION,
        "phase": response.get("phase") or pass_svc.PHASE,
        "source": "liveuin_public_pass_gateway",
        "canonical_owner": CANONICAL_OWNER,
        "surface": "liveuin_pass_public_gateway",
        "layer": "public_read_projection",
        "message": "LiveUIN public Pass verification projection loaded.",
        "viewer_scope": PUBLIC_VIEWER_SCOPE,
        "brand": brand,
        "metadata": {
            "canonical_owner": CANONICAL_OWNER,
            "last_event_at": _safe_str(metadata.get("last_event_at")),
            "last_event_type": _safe_str(metadata.get("last_event_type")),
            "source_system": _safe_str(metadata.get("source_system")),
            "surface": _safe_str(metadata.get("surface"), "liveuin_pass_public_gateway"),
        },
        "family": {
            "case_id": case_id,
            "status": _safe_str(response.get("status")),
            "status_group": _safe_str(response.get("status_group")),
            "school": _safe_str(_as_dict(response.get("family")).get("school")),
            "source": "liveuin_public_pass_gateway",
            "canonical": True,
        },
        "proof": [
            {
                "status": _safe_str(proof.get("status")),
                "title": _safe_str(proof.get("title")),
                "summary": _safe_str(proof.get("summary")),
                "updated_at": _safe_str(proof.get("updated_at")),
                "risk": {"level": _safe_str(_as_dict(proof.get("risk")).get("level"))},
            }
        ] if proof else [],
        "verification": {
            "summary": {
                "verified_count": int(verification_summary.get("verified_count") or 0),
                "review_required_count": int(verification_summary.get("review_required_count") or 0),
                "blocked_count": int(verification_summary.get("blocked_count") or 0),
                "profile_count": int(verification_summary.get("profile_count") or len(profiles)),
                "publish_gate": _safe_str(verification_summary.get("publish_gate")),
                "trust_badges": [str(item) for item in _as_list(verification_summary.get("trust_badges"))[:4]],
                "documents_hidden": True,
                "provider_payload_hidden": True,
                "property_proof_separate": True,
            },
            "profiles": profiles,
            "source": "liveuin_trust_identity",
            "canonical": True,
        },
        "movein": {
            "summary": {
                "blocker_count": int(movein_summary.get("blocker_count") or 0),
                "handover_at": _safe_str(movein_summary.get("handover_at")),
            },
            "latest_card": {
                "publish_gate": _safe_str(latest_card.get("publish_gate")),
                "handover_at": _safe_str(latest_card.get("handover_at")),
                "support_window_ends_at": _safe_str(latest_card.get("support_window_ends_at")),
                "checklist": safe_checklist,
            },
            "source": "liveuin_movein",
            "canonical": True,
        },
        "public_result": {
            "status": public_status,
            "verification_level": public_level,
            "trust_class": {
                "code": public_level["code"],
                "title": public_level["title"],
            },
            "verification_id": _safe_str(response.get("pass_id") or case_id),
            "display": _public_display_overrides(case_id, workspace_id),
            "verification_owner": "LiveUIN",
            "authorized_view_required": True,
        },
        "bookings": [],
        "payments": [],
        "booking_payments": [],
        "media_grants": [],
        "protected_media": [],
        "tickets": [],
        "operator_tasks": [],
        "viewings": [],
        "holds": [],
        "lifecycle": {},
        "resolution": {},
    }
    if _contains_private_fragment(projection):
        return {
            "ok": False,
            "detail": "public_projection_private_fragment_detected",
            "status_code": 500,
        }
    return projection


def _decorate(response: Dict[str, Any], *, public_gateway_status: str) -> Dict[str, Any]:
    response = response if isinstance(response, dict) else {}
    return {
        **response,
        "public_gateway": {
            "ok": response.get("ok") is not False,
            "schema_version": SCHEMA_VERSION,
            "phase": PHASE,
            "surface": SURFACE,
            "required_scope": READ_SCOPE,
            "mode": "read_only",
            "status": public_gateway_status,
            "canonical_owner": CANONICAL_OWNER,
            "mutation_routes_exposed": False,
            "connector_transport_only": True,
            "channel_truth_owner": False,
        },
    }


def public_pass_status() -> Dict[str, Any]:
    store_blocker = _projection_store_root_blocker()
    if store_blocker:
        return {
            "ok": False,
            "schema_version": SCHEMA_VERSION,
            "phase": PHASE,
            "source": "liveuin_public_pass_gateway",
            "surface": "liveuin_pass_public_gateway",
            "canonical_owner": CANONICAL_OWNER,
            "status": "private_store_root_forbidden",
            "detail": "public_pass_private_store_root_forbidden",
            "status_code": 503,
            "safe_projection_store": {
                "schema_version": projection_store.SCHEMA_VERSION,
                "mode": "projection_store_health_only",
                "projection_root_guard_checked": True,
                "private_store_direct_read_allowed": False,
                "root_switching_allowed": False,
                "permission_broadening_allowed": False,
                "canonical_status_reader_used": False,
                "canonical_storage_locations_exposed": False,
                "canonical_record_totals_exposed": False,
                "internal_endpoint_list_exposed": False,
            },
            "public_gateway": {
                "ok": False,
                "schema_version": SCHEMA_VERSION,
                "phase": PHASE,
                "required_scope": READ_SCOPE,
                "mode": "read_only",
                "status": "private_store_root_forbidden",
                "canonical_owner": CANONICAL_OWNER,
                "write_operations_available": False,
                "connector_transport_only": True,
                "channel_truth_owner": False,
            },
        }
    return {
        "ok": True,
        "schema_version": SCHEMA_VERSION,
        "phase": PHASE,
        "source": "liveuin_public_pass_gateway",
        "surface": "liveuin_pass_public_gateway",
        "canonical_owner": CANONICAL_OWNER,
        "status": "public_pass_projection_gateway_available",
        "safe_projection_store": {
            "schema_version": projection_store.SCHEMA_VERSION,
            "mode": "projection_store_health_only",
            "projection_root_guard_checked": True,
            "private_store_direct_read_allowed": False,
            "root_switching_allowed": False,
            "permission_broadening_allowed": False,
            "canonical_status_reader_used": False,
            "canonical_storage_locations_exposed": False,
            "canonical_record_totals_exposed": False,
            "internal_endpoint_list_exposed": False,
        },
        "public_gateway": {
            "ok": True,
            "schema_version": SCHEMA_VERSION,
            "phase": PHASE,
            "required_scope": READ_SCOPE,
            "mode": "read_only",
            "status": "projection_store_health_loaded",
            "canonical_owner": CANONICAL_OWNER,
            "write_operations_available": False,
            "connector_transport_only": True,
            "channel_truth_owner": False,
        },
    }


def materialize_public_pass_projection(
    case_id: str,
    workspace_id: str = pass_svc.DEFAULT_WORKSPACE_ID,
    *,
    materialized_by: str = "liveuin_core_projection_materializer",
    expires_at: int = 0,
) -> Dict[str, Any]:
    case_id = _clean_id(case_id)
    workspace_id = _clean_id(workspace_id) or pass_svc.DEFAULT_WORKSPACE_ID
    if not case_id:
        return {"ok": False, "detail": "case_id_required", "status_code": 400}
    upstream = pass_svc.pass_payload(case_id, workspace_id)
    if upstream.get("ok") is False:
        return upstream
    projected = _public_projection(upstream)
    return projection_store.upsert_projection(
        {
            "workspace_id": workspace_id,
            "case_id": case_id,
            "pass_id": projected.get("pass_id") or case_id,
            "projection": projected,
            "source_schema_version": str(upstream.get("schema_version") or pass_svc.SCHEMA_VERSION),
            "source_revision": str(upstream.get("metadata", {}).get("last_event_at") or upstream.get("updated_at") or ""),
            "materialized_by": materialized_by,
            "expires_at": int(expires_at or 0),
        }
    )


def public_pass_payload(
    case_id: str,
    workspace_id: str = pass_svc.DEFAULT_WORKSPACE_ID,
    *,
    grant_id: str = "",
    participant_id: str = "",
    purpose: str = PUBLIC_PASS_PURPOSE,
    recipient: str = PUBLIC_PASS_RECIPIENT,
) -> Dict[str, Any]:
    case_id = _clean_id(case_id)
    workspace_id = _clean_id(workspace_id) or pass_svc.DEFAULT_WORKSPACE_ID
    if not case_id:
        return _decorate(
            {"ok": False, "detail": "case_id_required", "status_code": 400},
            public_gateway_status="case_id_required",
        )
    store_blocker = _projection_store_root_blocker()
    if store_blocker:
        return _decorate(
            {"ok": False, "detail": store_blocker, "status_code": 503},
            public_gateway_status="private_store_root_forbidden",
        )
    grant = _projection_grant(
        workspace_id=workspace_id,
        case_id=case_id,
        grant_id=_clean_id(grant_id, 140),
        participant_id=_clean_id(participant_id, 120),
        purpose=purpose,
        recipient=recipient,
    )
    if grant.get("ok") is not True:
        return _decorate(grant, public_gateway_status="participant_grant_denied")

    projection_record = projection_store.get_projection(case_id, workspace_id)
    if projection_record.get("ok") is not True:
        return _decorate(projection_record, public_gateway_status="public_projection_unavailable")
    freshness_blocker = _projection_freshness_blocker(projection_record)
    if freshness_blocker:
        return _decorate(
            {"ok": False, "detail": freshness_blocker, "status_code": 503, "projection_record": projection_record},
            public_gateway_status="public_projection_unavailable",
        )
    projected = _as_dict(projection_record.get("projection"))
    projected["grant_controls"] = {
        "grant_id": _safe_str(_as_dict(grant.get("participant_grant")).get("grant_id")),
        "case_bound": True,
        "purpose": purpose,
        "recipient": recipient,
        "disclosure_model": PUBLIC_PASS_DISCLOSURE_MODEL,
        "revocation_enforced": True,
        "direct_private_store_root_allowed": False,
        "opportunistic_store_switching_allowed": False,
        "permission_broadening_allowed": False,
    }
    projected["safe_projection_controls"] = {
        "projection_hash": _safe_str(projection_record.get("projection_hash")),
        "source_schema_version": _safe_str(projection_record.get("source_schema_version")),
        "materialized_by": _safe_str(projection_record.get("materialized_by")),
        "updated_at": int(projection_record.get("updated_at") or 0),
        "public_reader_uses_projection_store_only": True,
        "private_case_pass_store_read_allowed": False,
        "direct_srv_liveuin_read_allowed": False,
    }
    return _decorate(projected, public_gateway_status="pass_loaded")


def build_router(require_api_key: Callable[..., Dict[str, Any]]) -> Any:
    """Build the read-only public gateway router.

    The hardened public API app injects its own API-key verifier here. This
    module deliberately exposes no write/mutation routes and creates no product
    truth; it only reads the canonical LiveUIN Pass aggregate.
    """

    from fastapi import APIRouter, Depends, Header, HTTPException, Query

    router = APIRouter()

    def _require_read_key(request: Any = None, x_liveuin_api_key: str | None = Header(default=None, alias="X-LiveUin-Api-Key")) -> Dict[str, Any]:
        return require_api_key(api_key=x_liveuin_api_key, required_scope=READ_SCOPE, request=request)

    @router.get("/api/pass/status", dependencies=[Depends(_require_read_key)])
    def _status() -> Dict[str, Any]:
        response = public_pass_status()
        if response.get("ok") is False:
            raise HTTPException(
                status_code=int(response.get("status_code") or 500),
                detail=str(response.get("detail") or "public_pass_status_error"),
            )
        return response

    @router.get("/api/pass/{case_id}", dependencies=[Depends(_require_read_key)])
    def _get_pass(
        case_id: str,
        workspace_id: str = Query(pass_svc.DEFAULT_WORKSPACE_ID, max_length=96),
        grant_id: str = Query("", max_length=140),
        participant_id: str = Query("", max_length=120),
    ) -> Dict[str, Any]:
        response = public_pass_payload(case_id, workspace_id, grant_id=grant_id, participant_id=participant_id)
        if response.get("ok") is False:
            raise HTTPException(
                status_code=int(response.get("status_code") or 404),
                detail=str(response.get("detail") or "public_pass_read_error"),
            )
        return response

    return router


def mount_public_pass_routes(app: Any, require_api_key: Callable[..., Dict[str, Any]]) -> None:
    app.include_router(build_router(require_api_key))

