def _body_bytes(raw_body: Any) -> bytes:
    if isinstance(raw_body, bytes):
        return raw_body
    if isinstance(raw_body, bytearray):
        return bytes(raw_body)
    if isinstance(raw_body, str):
        return raw_body.encode("utf-8")
    if isinstance(raw_body, dict):
        return json.dumps(raw_body, ensure_ascii=True, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return str(raw_body or "").encode("utf-8")


def _headers(headers: Dict[str, Any] | None) -> Dict[str, str]:
    clean: Dict[str, str] = {}
    for key, value in (headers or {}).items():
        clean[str(key).strip().lower()] = str(value or "").strip()
    return clean


def _env(*names: str) -> str:
    for name in names:
        value = str(os.getenv(name) or "").strip()
        if value:
            return value
    return ""


def _env_bool(*names: str) -> bool:
    return _env(*names).lower() in {"1", "true", "yes", "on", "verified", "enabled"}


