def _clean_id(value: Any, max_length: int = 160) -> str:
    cleaned = "".join(ch for ch in str(value or "").strip() if ch.isalnum() or ch in "_.:-")
    return cleaned[:max_length]


def _clean_provider(value: Any) -> str:
    cleaned = "".join(ch if ch.isalnum() else "_" for ch in str(value or "").strip().lower()).strip("_")
    return cleaned[:80] or "payment_provider"


def _to_int(value: Any, default: int = 0) -> int:
    try:
        return int(value)
    except (TypeError, ValueError):
        return default


def _as_dict(value: Any) -> Dict[str, Any]:
    return value if isinstance(value, dict) else {}


def _as_public_secret_context(resolution: Dict[str, Any] | None) -> Dict[str, Any]:
    context = _as_dict(_as_dict(resolution).get("secret_context"))
    return {
        key: value
        for key, value in context.items()
        if key
        not in {
            "secret",
            "raw_secret",
            "api_key",
            "endpoint_secret",
            "webhook_salt",
            "api_v3_key",
        }
    }


def _provider_key(value: Any) -> str:
    provider = str(value or "").strip().lower().replace("-", "_")
    if provider in {"wechat", "wechatpay", "wechat_pay"}:
        return "wechat_pay"
    return provider


def _secret_purpose(provider: str, purpose: str = "") -> str:
    provider = _provider_key(provider)
    cleaned = str(purpose or "").strip().lower().replace("-", "_")
    if provider == "stripe" and cleaned in {"", "webhook", "webhook_signature", "endpoint_secret"}:
        return "stripe_webhook_signature"
    if provider == "hitpay" and cleaned in {"", "webhook", "webhook_signature", "webhook_salt"}:
        return "hitpay_webhook_signature"
    if provider == "wechat_pay" and cleaned in {"", "api_v3", "api_v3_key"}:
        return "wechat_pay_api_v3_key"
    return cleaned


def _fallback_secret_context(provider: str, purpose: str, secret: str, source: str) -> Dict[str, Any]:
