def _provider_secret_resolution(
    provider: str,
    purpose: str,
    explicit_secret: str = "",
    *,
    workspace_id: str = DEFAULT_WORKSPACE_ID,
    secret_ref_id: str = "",
) -> Dict[str, Any]:
    provider = _provider_key(provider)
    purpose = _secret_purpose(provider, purpose)
    if secret_registry is not None:
        resolved = secret_registry.resolve_provider_edge_secret(
            provider,
            purpose,
            workspace_id=workspace_id or DEFAULT_WORKSPACE_ID,
            explicit_secret=explicit_secret,
            secret_ref_id=secret_ref_id,
        )
        if resolved.get("ok") is True or explicit_secret:
            return resolved
        if resolved.get("detail") == "adapter_secret_reference_inactive":
            return resolved

    if explicit_secret:
        return {
            "ok": True,
            "secret": explicit_secret,
            "secret_context": _fallback_secret_context(provider, purpose, explicit_secret, "explicit_route_secret"),
        }
    if provider == "stripe":
        secret = stripe_endpoint_secret()
    elif provider == "hitpay":
        secret = hitpay_webhook_salt()
    elif provider == "wechat_pay":
        secret = wechat_pay_api_v3_key()
    else:
        secret = ""
    return {
        "ok": bool(secret),
        "secret": secret,
        "secret_context": _fallback_secret_context(provider, purpose, secret, "legacy_provider_edge_env"),
    }


