def _parse_json_body(raw_body: Any, provider: str) -> Tuple[Dict[str, Any], Dict[str, Any] | None]:
    if isinstance(raw_body, dict):
        return raw_body, None
    try:
        decoded = _body_bytes(raw_body).decode("utf-8")
        parsed = json.loads(decoded)
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        return {}, _edge_error(provider, "invalid_json_provider_payload", 400, parse_error_type=exc.__class__.__name__)
    if not isinstance(parsed, dict):
        return {}, _edge_error(provider, "provider_payload_must_be_object", 400)
    return parsed, None


def _parse_form_body(raw_body: Any, provider: str) -> Tuple[Dict[str, Any], Dict[str, Any] | None]:
    if isinstance(raw_body, dict):
        return {str(key): value for key, value in raw_body.items()}, None
    try:
        decoded = _body_bytes(raw_body).decode("utf-8")
    except UnicodeDecodeError as exc:
        return {}, _edge_error(provider, "invalid_provider_payload_encoding", 400, parse_error_type=exc.__class__.__name__)
    parsed = parse_qsl(decoded, keep_blank_values=True)
    if not parsed:
        return {}, _edge_error(provider, "provider_payload_must_be_form_encoded", 400)
    return {key: value for key, value in parsed}, None


def _parse_stripe_signature_header(signature_header: str) -> Tuple[int, List[str]]:
    timestamp = 0
    signatures: List[str] = []
    for part in str(signature_header or "").split(","):
        key, separator, value = part.partition("=")
        if not separator:
            continue
        key = key.strip()
        value = value.strip()
        if key == "t":
            try:
                timestamp = int(value)
            except ValueError:
                timestamp = 0
        elif key == "v1" and value:
            signatures.append(value)
    return timestamp, signatures


def verify_stripe_signature(
    raw_body: Any,
    signature_header: str,
    endpoint_secret: str = "",
    *,
    tolerance_seconds: int = DEFAULT_STRIPE_TOLERANCE_SECONDS,
    now: int | None = None,
    workspace_id: str = DEFAULT_WORKSPACE_ID,
    secret_ref_id: str = "",
) -> Dict[str, Any]:
    body = _body_bytes(raw_body)
    secret_resolution = _provider_secret_resolution(
        "stripe",
        "stripe_webhook_signature",
        endpoint_secret,
        workspace_id=workspace_id,
        secret_ref_id=secret_ref_id,
    )
    endpoint_secret = str(secret_resolution.get("secret") or "")
    secret_context = _as_public_secret_context(secret_resolution)
    if not endpoint_secret:
        return _edge_error(
            "stripe",
            "stripe_endpoint_secret_required",
            500,
            payload_hash=_hash_bytes(body),
            secret_context=secret_context,
        )
    if not signature_header:
        return _edge_error(
            "stripe",
            "stripe_signature_header_required",
            401,
            payload_hash=_hash_bytes(body),
            secret_context=secret_context,
        )

    timestamp, signatures = _parse_stripe_signature_header(signature_header)
    if timestamp <= 0 or not signatures:
        return _edge_error(
            "stripe",
            "stripe_signature_header_invalid",
            401,
            payload_hash=_hash_bytes(body),
            signature_header_hash=_hash_text(signature_header),
            secret_context=secret_context,
        )

    current_time = int(now if now is not None else time.time())
    tolerance = max(1, int(tolerance_seconds or DEFAULT_STRIPE_TOLERANCE_SECONDS))
    skew = abs(current_time - timestamp)
    if skew > tolerance:
        return _edge_error(
            "stripe",
            "stripe_signature_timestamp_outside_tolerance",
            401,
            payload_hash=_hash_bytes(body),
            signature_header_hash=_hash_text(signature_header),
            timestamp=timestamp,
            clock_skew_seconds=skew,
            tolerance_seconds=tolerance,
            secret_context=secret_context,
        )

    signed_payload = str(timestamp).encode("utf-8") + b"." + body
    expected = hmac.new(endpoint_secret.encode("utf-8"), signed_payload, hashlib.sha256).hexdigest()
    matched = any(hmac.compare_digest(expected, candidate) for candidate in signatures)
    if not matched:
        return _edge_error(
            "stripe",
            "stripe_signature_mismatch",
            401,
            payload_hash=_hash_bytes(body),
            signature_header_hash=_hash_text(signature_header),
            timestamp=timestamp,
            secret_context=secret_context,
        )

    return _edge_base(
        "stripe",
        "transport_signature_verified",
        transport_signature_verified=True,
        payload_hash=_hash_bytes(body),
        signature_header_hash=_hash_text(signature_header),
        timestamp=timestamp,
        clock_skew_seconds=skew,
        tolerance_seconds=tolerance,
        secret_context=secret_context,
    )


def normalize_stripe_webhook(
    raw_body: Any,
    headers: Dict[str, Any],
    endpoint_secret: str = "",
    *,
    tolerance_seconds: int = DEFAULT_STRIPE_TOLERANCE_SECONDS,
    now: int | None = None,
    fallback_amount: int = 0,
    fallback_currency: str = "SGD",
    workspace_id: str = DEFAULT_WORKSPACE_ID,
    secret_ref_id: str = "",
) -> Dict[str, Any]:
    header_map = _headers(headers)
    verification = verify_stripe_signature(
        raw_body,
        header_map.get("stripe-signature", ""),
        endpoint_secret,
        tolerance_seconds=tolerance_seconds,
        now=now,
        workspace_id=workspace_id,
        secret_ref_id=secret_ref_id,
    )
    if verification.get("ok") is False:
        return verification

    payload, parse_error = _parse_json_body(raw_body, "stripe")
    if parse_error:
        return parse_error
    normalized = provider_adapter.normalize_provider_event(
        payload,
        fallback_provider="stripe",
        fallback_amount=fallback_amount,
        fallback_currency=fallback_currency,
    )
    if normalized.get("ok") is False:
        return normalized
    return _edge_base(
        "stripe",
        "provider_webhook_normalized",
        transport_signature_verified=True,
        provider_edge=verification,
        provider_event=normalized.get("provider_event", {}),
        provider_adapter=normalized.get("provider_adapter", {}),
    )


def verify_hitpay_signature(
    raw_body: Any,
    signature_header: str,
    webhook_salt: str = "",
    *,
    workspace_id: str = DEFAULT_WORKSPACE_ID,
    secret_ref_id: str = "",
) -> Dict[str, Any]:
    body = _body_bytes(raw_body)
    secret_resolution = _provider_secret_resolution(
        "hitpay",
        "hitpay_webhook_signature",
        webhook_salt,
        workspace_id=workspace_id,
        secret_ref_id=secret_ref_id,
    )
    webhook_salt = str(secret_resolution.get("secret") or "")
    secret_context = _as_public_secret_context(secret_resolution)
    if not webhook_salt:
        return _edge_error(
            "hitpay",
            "hitpay_webhook_salt_required",
            500,
            payload_hash=_hash_bytes(body),
            secret_context=secret_context,
        )
    if not signature_header:
        return _edge_error(
            "hitpay",
            "hitpay_signature_header_required",
            401,
            payload_hash=_hash_bytes(body),
            secret_context=secret_context,
        )

    expected = hmac.new(webhook_salt.encode("utf-8"), body, hashlib.sha256).hexdigest()
    candidate = str(signature_header or "").strip().lower()
    if not hmac.compare_digest(expected, candidate):
        return _edge_error(
            "hitpay",
            "hitpay_signature_mismatch",
            401,
            payload_hash=_hash_bytes(body),
            signature_header_hash=_hash_text(signature_header),
            secret_context=secret_context,
        )
    return _edge_base(
        "hitpay",
        "transport_signature_verified",
        transport_signature_verified=True,
        payload_hash=_hash_bytes(body),
        signature_header_hash=_hash_text(signature_header),
        secret_context=secret_context,
    )


def _hitpay_event_type(headers: Dict[str, str]) -> str:
    event_type = headers.get("hitpay-event-type", "")
    event_object = headers.get("hitpay-event-object", "")
    if event_object == "payment_request" and event_type:
        return "payment_request." + event_type
    if event_object and event_type:
        return event_object + "." + event_type
    return ""


def normalize_hitpay_webhook(
    raw_body: Any,
    headers: Dict[str, Any],
    webhook_salt: str = "",
    *,
    fallback_amount: int = 0,
    fallback_currency: str = "SGD",
    workspace_id: str = DEFAULT_WORKSPACE_ID,
    secret_ref_id: str = "",
) -> Dict[str, Any]:
    header_map = _headers(headers)
    verification = verify_hitpay_signature(
        raw_body,
        header_map.get("hitpay-signature", ""),
        webhook_salt,
        workspace_id=workspace_id,
        secret_ref_id=secret_ref_id,
    )
    if verification.get("ok") is False:
        return verification

    payload, parse_error = _parse_json_body(raw_body, "hitpay")
    if parse_error:
        return parse_error
    event_type = _hitpay_event_type(header_map)
    if event_type and "event_type" not in payload:
        payload = {**payload, "event_type": event_type}
    normalized = provider_adapter.normalize_provider_event(
        payload,
        fallback_provider="hitpay",
        fallback_amount=fallback_amount,
        fallback_currency=fallback_currency,
    )
    if normalized.get("ok") is False:
        return normalized
    return _edge_base(
        "hitpay",
        "provider_webhook_normalized",
        transport_signature_verified=True,
        provider_edge=verification,
        provider_event=normalized.get("provider_event", {}),
        provider_adapter=normalized.get("provider_adapter", {}),
    )


def inspect_wechat_pay_headers(headers: Dict[str, Any] | None, raw_body: Any = b"") -> Dict[str, Any]:
    header_map = _headers(headers)
    timestamp = header_map.get("wechatpay-timestamp", "")
    nonce = header_map.get("wechatpay-nonce", "")
    serial = header_map.get("wechatpay-serial", "")
    signature = header_map.get("wechatpay-signature", "")
    missing = [
        name
        for name, value in (
            ("Wechatpay-Timestamp", timestamp),
            ("Wechatpay-Nonce", nonce),
            ("Wechatpay-Serial", serial),
            ("Wechatpay-Signature", signature),
        )
        if not value
    ]
    signature_message_hash = ""
    if timestamp and nonce:
        signature_message = timestamp.encode("utf-8") + b"\n" + nonce.encode("utf-8") + b"\n" + _body_bytes(raw_body) + b"\n"
        signature_message_hash = _hash_bytes(signature_message)
    return _edge_base(
        "wechat_pay",
        "wechat_pay_transport_headers_inspected",
        transport_signature_verified=False,
        platform_signature_verifier_mounted=False,
        signature_verification_required=True,
        missing_headers=missing,
        platform_serial_hash=_hash_text(serial) if serial else "",
        signature_hash=_hash_text(signature) if signature else "",
        signature_message_hash=signature_message_hash,
        payload_hash=_hash_bytes(_body_bytes(raw_body)) if raw_body else "",
    )


def _wechat_review(payload: Dict[str, Any], edge_status: str, headers: Dict[str, Any] | None = None, raw_body: Any = b"") -> Dict[str, Any]:
    normalized = provider_adapter.normalize_provider_event(
        payload,
        fallback_provider="wechat_pay",
        fallback_amount=0,
        fallback_currency="CNY",
    )
    provider_adapter_context = normalized.get("provider_adapter", {}) if normalized.get("ok") is not False else {}
    provider_event = normalized.get("provider_event", {}) if normalized.get("ok") is not False else {}
    warnings = list(provider_adapter_context.get("provider_adapter_warnings") or [])
    if edge_status not in warnings:
        warnings.append(edge_status)
    provider_adapter_context = {**provider_adapter_context, "provider_adapter_warnings": warnings}
    provider_event = {**provider_event, "provider_adapter_warnings": warnings, "status": "requires_review", "provider_status": "requires_review"}
    return _edge_base(
        "wechat_pay",
        edge_status,
        transport_signature_verified=False,
        provider_edge=inspect_wechat_pay_headers(headers, raw_body),
        provider_event=provider_event,
        provider_adapter=provider_adapter_context,
    )


def _decrypt_wechat_pay_resource(
    notification: Dict[str, Any],
    api_v3_key: str,
    secret_context: Dict[str, Any] | None = None,
) -> Dict[str, Any]:
    resource = notification.get("resource") if isinstance(notification.get("resource"), dict) else {}
    algorithm = str(resource.get("algorithm") or "").strip()
    if algorithm != "AEAD_AES_256_GCM":
        return _edge_error("wechat_pay", "wechat_pay_unsupported_resource_algorithm", 400, algorithm=algorithm)
    if not api_v3_key:
        return _edge_error("wechat_pay", "wechat_pay_api_v3_key_required", 500, secret_context=_as_dict(secret_context))
    key = api_v3_key.encode("utf-8")
    if len(key) != 32:
        return _edge_error("wechat_pay", "wechat_pay_api_v3_key_must_be_32_bytes", 500, secret_context=_as_dict(secret_context))
    aesgcm = _load_aesgcm()
    if not CRYPTOGRAPHY_AVAILABLE or aesgcm is None:
        return _edge_error(
            "wechat_pay",
            "wechat_pay_decryption_dependency_missing",
            501,
            required_python_package="cryptography",
            secret_context=_as_dict(secret_context),
        )

    ciphertext_text = str(resource.get("ciphertext") or "")
    nonce = str(resource.get("nonce") or "").encode("utf-8")
    associated_data = str(resource.get("associated_data") or "").encode("utf-8")
    try:
        ciphertext = base64.b64decode(ciphertext_text)
        plaintext = aesgcm(key).decrypt(nonce, ciphertext, associated_data)
        decrypted = json.loads(plaintext.decode("utf-8"))
    except Exception as exc:  # pragma: no cover - exercised only when cryptography exists.
        return _edge_error(
            "wechat_pay",
            "wechat_pay_resource_decryption_failed",
            400,
            decrypt_error_type=exc.__class__.__name__,
            encrypted_resource_hash=_hash_text(ciphertext_text),
            secret_context=_as_dict(secret_context),
        )
    if not isinstance(decrypted, dict):
        return _edge_error(
            "wechat_pay",
            "wechat_pay_decrypted_resource_must_be_object",
            400,
            secret_context=_as_dict(secret_context),
        )
    return _edge_base(
        "wechat_pay",
        "wechat_pay_resource_decrypted",
        decrypted_resource=decrypted,
        encrypted_resource_hash=_hash_text(ciphertext_text),
        decrypted_resource_hash=_hash_bytes(json.dumps(decrypted, ensure_ascii=True, sort_keys=True).encode("utf-8")),
        secret_context=_as_dict(secret_context),
    )


def normalize_wechat_pay_notification(
    raw_body: Any,
    headers: Dict[str, Any] | None,
    api_v3_key: str = "",
    *,
    platform_signature_verified: bool = False,
    allow_unsigned_decryption: bool = False,
    workspace_id: str = DEFAULT_WORKSPACE_ID,
    secret_ref_id: str = "",
) -> Dict[str, Any]:
    payload, parse_error = _parse_json_body(raw_body, "wechat_pay")
    if parse_error:
        return parse_error

    header_context = inspect_wechat_pay_headers(headers, raw_body)
    can_decrypt = platform_signature_verified or allow_unsigned_decryption
    if not can_decrypt:
        return _wechat_review(payload, "wechat_pay_platform_signature_verification_required", headers, raw_body)

    secret_resolution = _provider_secret_resolution(
        "wechat_pay",
        "wechat_pay_api_v3_key",
        api_v3_key,
        workspace_id=workspace_id,
        secret_ref_id=secret_ref_id,
    )
    secret_context = _as_public_secret_context(secret_resolution)
    decrypted = _decrypt_wechat_pay_resource(payload, str(secret_resolution.get("secret") or ""), secret_context)
    if decrypted.get("ok") is False:
        return _wechat_review(payload, str(decrypted.get("detail") or "wechat_pay_resource_decryption_failed"), headers, raw_body)

    normalized_payload = {**payload, "decrypted_resource": decrypted.get("decrypted_resource", {})}
    normalized = provider_adapter.normalize_provider_event(
        normalized_payload,
        fallback_provider="wechat_pay",
        fallback_amount=0,
        fallback_currency="CNY",
    )
    if normalized.get("ok") is False:
        return normalized
    return _edge_base(
        "wechat_pay",
        "provider_webhook_normalized",
        transport_signature_verified=bool(platform_signature_verified),
        platform_signature_verifier_mounted=bool(platform_signature_verified),
        unsigned_decryption_allowed_for_local_contract=bool(allow_unsigned_decryption and not platform_signature_verified),
        provider_edge={
            **header_context,
            "secret_context": secret_context,
            "decryption": {k: v for k, v in decrypted.items() if k != "decrypted_resource"},
        },
        provider_event=normalized.get("provider_event", {}),
        provider_adapter=normalized.get("provider_adapter", {}),
    )


def _alipay_presign_string(payload: Dict[str, Any]) -> str:
    parts: List[str] = []
    for key in sorted(payload):
        if key in {"sign", "sign_type"}:
            continue
        value = payload.get(key)
        if isinstance(value, list):
            value = ",".join(str(item) for item in value)
        parts.append(f"{key}={value}")
    return "&".join(parts)


def _alipay_der_length(data: bytes, offset: int) -> Tuple[int, int]:
    if offset >= len(data):
        raise ValueError("alipay_der_length_out_of_range")
    first = data[offset]
    offset += 1
    if first < 0x80:
        return first, offset
    count = first & 0x7F
    if count <= 0 or count > 4 or offset + count > len(data):
        raise ValueError("alipay_der_length_invalid")
    length = int.from_bytes(data[offset : offset + count], "big")
    return length, offset + count


def _alipay_der_tlv(data: bytes, offset: int) -> Tuple[int, bytes, int]:
    if offset >= len(data):
        raise ValueError("alipay_der_tlv_out_of_range")
    tag = data[offset]
    length, value_offset = _alipay_der_length(data, offset + 1)
    end = value_offset + length
    if end > len(data):
        raise ValueError("alipay_der_tlv_overflow")
    return tag, data[value_offset:end], end


def _alipay_extract_public_numbers(public_key_pem: str) -> Tuple[int, int]:
    pem = str(public_key_pem or "").strip()
    if "BEGIN PUBLIC KEY" in pem:
        begin = "-----BEGIN PUBLIC KEY-----"
        end = "-----END PUBLIC KEY-----"
    elif "BEGIN RSA PUBLIC KEY" in pem:
        begin = "-----BEGIN RSA PUBLIC KEY-----"
        end = "-----END RSA PUBLIC KEY-----"
    else:
        raise ValueError("alipay_public_key_pem_invalid")
    body = "".join(line.strip() for line in pem.splitlines() if line and not line.startswith("-----"))
    der = base64.b64decode(body.encode("ascii"))
    tag, outer_value, offset = _alipay_der_tlv(der, 0)
    if tag != 0x30:
        raise ValueError("alipay_public_key_der_invalid")
    if "RSA PUBLIC KEY" in pem:
        seq_tag, seq_value, seq_end = 0, outer_value, offset  # placeholder for direct PKCS#1
    else:
        inner_offset = 0
        alg_tag, _, inner_offset = _alipay_der_tlv(outer_value, inner_offset)
        if alg_tag != 0x30:
            raise ValueError("alipay_public_key_algorithm_invalid")
        bit_tag, bit_value, inner_offset = _alipay_der_tlv(outer_value, inner_offset)
        if bit_tag != 0x03 or not bit_value:
            raise ValueError("alipay_public_key_bitstring_invalid")
        if bit_value[0] != 0:
            raise ValueError("alipay_public_key_unused_bits_invalid")
        seq_tag, seq_value, seq_end = _alipay_der_tlv(bit_value[1:], 0)
        if seq_tag != 0x30:
            raise ValueError("alipay_public_key_rsa_sequence_invalid")
        der = seq_value
    inner_offset = 0
    modulus_tag, modulus_value, inner_offset = _alipay_der_tlv(der, inner_offset)
    exponent_tag, exponent_value, inner_offset = _alipay_der_tlv(der, inner_offset)
    if modulus_tag != 0x02 or exponent_tag != 0x02:
        raise ValueError("alipay_public_key_integer_invalid")
    modulus = int.from_bytes(modulus_value, "big", signed=False)
    exponent = int.from_bytes(exponent_value, "big", signed=False)
    if modulus <= 0 or exponent <= 0:
        raise ValueError("alipay_public_key_numbers_invalid")
    return modulus, exponent


def _verify_alipay_signature_bytes(signing_payload: bytes, signature_value: str, sign_type: str, public_key_pem: str) -> Dict[str, Any]:
    signature_type = str(sign_type or "RSA2").strip().upper()
    if signature_type not in {"RSA", "RSA2"}:
        return _edge_error("alipay", "alipay_sign_type_invalid", 400, sign_type=signature_type)

    try:
        signature_bytes = base64.b64decode(signature_value.encode("utf-8"))
    except Exception as exc:
        return _edge_error("alipay", "alipay_signature_decode_failed", 401, parse_error_type=exc.__class__.__name__)

    try:
        modulus, exponent = _alipay_extract_public_numbers(public_key_pem)
    except Exception as exc:
        return _edge_error("alipay", "alipay_public_key_invalid", 500, parse_error_type=exc.__class__.__name__)

    key_bytes = (modulus.bit_length() + 7) // 8
    decrypted = pow(int.from_bytes(signature_bytes, "big"), exponent, modulus).to_bytes(key_bytes, "big")
    digest = hashlib.sha256(signing_payload).digest() if signature_type == "RSA2" else hashlib.sha1(signing_payload).digest()
    digest_prefix = ALIPAY_RSA_SHA256_DER_PREFIX if signature_type == "RSA2" else ALIPAY_RSA_SHA1_DER_PREFIX
    expected = digest_prefix + digest
    separator_index = key_bytes - len(expected) - 1
    if separator_index < 10:
        return _edge_error("alipay", "alipay_signature_mismatch", 401, sign_type=signature_type)
    if not (
        decrypted[0:2] == b"\x00\x01"
        and all(item == 0xFF for item in decrypted[2:separator_index])
        and decrypted[separator_index] == 0
        and hmac.compare_digest(decrypted[separator_index + 1 :], expected)
    ):
        return _edge_error(
            "alipay",
            "alipay_signature_mismatch",
            401,
            sign_type=signature_type,
            payload_hash=_hash_bytes(signing_payload),
            signature_hash=_hash_text(signature_value),
            signature_prefix=digest_prefix.hex(),
        )

    return _edge_base(
        "alipay",
        "transport_signature_verified",
        transport_signature_verified=True,
        sign_type=signature_type,
        payload_hash=_hash_bytes(signing_payload),
        signature_hash=_hash_text(signature_value),
    )


def verify_alipay_signature(
    raw_body: Any,
    signature: str,
    sign_type: str,
    public_key_pem: str = "",
    *,
    workspace_id: str = DEFAULT_WORKSPACE_ID,
    secret_ref_id: str = "",
) -> Dict[str, Any]:
    body, parse_error = _parse_form_body(raw_body, "alipay")
    if parse_error:
        return parse_error
    secret_resolution = _provider_secret_resolution(
        "alipay",
        "alipay_webhook_signature",
        public_key_pem,
        workspace_id=workspace_id,
        secret_ref_id=secret_ref_id,
    )
    public_key_pem = str(secret_resolution.get("secret") or "")
    secret_context = _as_public_secret_context(secret_resolution)
    if not public_key_pem:
        return _edge_error("alipay", "alipay_public_key_required", 500, secret_context=secret_context)
    signing_payload = _alipay_presign_string(body).encode("utf-8")
    verification = _verify_alipay_signature_bytes(signing_payload, signature, sign_type, public_key_pem)
    if verification.get("ok") is not True:
        return verification
    return _edge_base(
        "alipay",
        "transport_signature_verified",
        transport_signature_verified=True,
        payload_hash=_hash_bytes(_body_bytes(raw_body)),
        signature_hash=_hash_text(signature),
        sign_type=str(sign_type or "RSA2").strip().upper(),
        secret_context=secret_context,
    )


def normalize_alipay_webhook(
    raw_body: Any,
    headers: Dict[str, Any] | None,
    public_key_pem: str = "",
    *,
    fallback_amount: int = 0,
    fallback_currency: str = "CNY",
    workspace_id: str = DEFAULT_WORKSPACE_ID,
    secret_ref_id: str = "",
) -> Dict[str, Any]:
    header_map = _headers(headers)
    payload, parse_error = _parse_form_body(raw_body, "alipay")
    if parse_error:
        return parse_error
    verification = verify_alipay_signature(
        payload,
        str(payload.get("sign") or ""),
        str(payload.get("sign_type") or "RSA2"),
        public_key_pem,
        workspace_id=workspace_id,
        secret_ref_id=secret_ref_id,
    )
    if verification.get("ok") is not True:
        return verification
    normalized = provider_adapter.normalize_provider_event(
        payload,
        fallback_provider="alipay",
        fallback_amount=fallback_amount,
        fallback_currency=fallback_currency,
    )
    if normalized.get("ok") is False:
        return normalized
    return _edge_base(
        "alipay",
        "provider_webhook_normalized",
        transport_signature_verified=True,
        provider_edge=verification,
        provider_event=normalized.get("provider_event", {}),
        provider_adapter=normalized.get("provider_adapter", {}),
        provider_headers=header_map,
    )


def normalize_provider_webhook(
    provider: str,
    raw_body: Any,
    headers: Dict[str, Any] | None,
    *,
    workspace_id: str = DEFAULT_WORKSPACE_ID,
    secret_ref_id: str = "",
) -> Dict[str, Any]:
    provider_key = _provider_key(provider)
    if provider_key == "stripe":
        return normalize_stripe_webhook(
            raw_body,
            headers or {},
            workspace_id=workspace_id,
            secret_ref_id=secret_ref_id,
        )
    if provider_key == "hitpay":
        return normalize_hitpay_webhook(
            raw_body,
            headers or {},
            workspace_id=workspace_id,
            secret_ref_id=secret_ref_id,
        )
    if provider_key == "wechat_pay":
        return normalize_wechat_pay_notification(
            raw_body,
            headers or {},
            platform_signature_verified=wechat_pay_platform_signature_verified(),
            allow_unsigned_decryption=wechat_pay_allow_unsigned_decryption(),
            workspace_id=workspace_id,
            secret_ref_id=secret_ref_id,
        )
    if provider_key == "alipay":
        return normalize_alipay_webhook(
            raw_body,
            headers or {},
            alipay_webhook_public_key(),
            workspace_id=workspace_id,
            secret_ref_id=secret_ref_id,
        )
    return _edge_error(
        provider_key.replace("_", "-") or "unknown",
        "payment_provider_not_supported",
        404,
        supported_providers=["stripe", "hitpay", "wechat-pay", "alipay"],
    )


def _local_raw_body(payload: Dict[str, Any] | None) -> Any:
    payload = payload if isinstance(payload, dict) else {}
    if "raw_body" in payload:
        return payload.get("raw_body")
    if "body" in payload:
        return payload.get("body")
    if isinstance(payload.get("provider_payload"), dict):
        return json.dumps(payload.get("provider_payload"), ensure_ascii=True, sort_keys=True, separators=(",", ":"))
    return json.dumps(payload, ensure_ascii=True, sort_keys=True, separators=(",", ":"))


def normalize_provider_webhook_payload(
    provider: str,
    payload: Dict[str, Any] | None,
    request_headers: Dict[str, Any] | None = None,
) -> Dict[str, Any]:
    payload = payload if isinstance(payload, dict) else {}
    payload_headers = payload.get("headers") if isinstance(payload.get("headers"), dict) else {}
    headers = {**(request_headers or {}), **payload_headers}
    return normalize_provider_webhook(
        provider,
        _local_raw_body(payload),
        headers,
        workspace_id=_workspace_from(headers, payload),
        secret_ref_id=_clean_id(payload.get("secret_ref_id") or payload.get("provider_secret_ref_id"), 160),
    )


def _edge_context(edge_result: Dict[str, Any]) -> Dict[str, Any]:
    edge_result = edge_result if isinstance(edge_result, dict) else {}
    provider_edge = edge_result.get("provider_edge") if isinstance(edge_result.get("provider_edge"), dict) else {}
    secret_context = provider_edge.get("secret_context") if isinstance(provider_edge.get("secret_context"), dict) else {}
    return {
        "schema_version": edge_result.get("schema_version", SCHEMA_VERSION),
        "phase": edge_result.get("phase", PHASE),
        "provider": edge_result.get("provider", ""),
        "status": edge_result.get("status", ""),
        "transport_signature_verified": bool(edge_result.get("transport_signature_verified")),
        "payload_hash": provider_edge.get("payload_hash", ""),
        "signature_header_hash": provider_edge.get("signature_header_hash", ""),
        "platform_serial_hash": provider_edge.get("platform_serial_hash", ""),
        "signature_message_hash": provider_edge.get("signature_message_hash", ""),
        "secret_source": secret_context.get("secret_source", ""),
        "secret_ref_id": secret_context.get("secret_ref_id", ""),
        "secret_hash_prefix": secret_context.get("secret_hash_prefix", ""),
        "provider_truth_used": False,
        "raw_provider_payload_stored": False,
    }


def provider_event_payload_from_edge(
    edge_result: Dict[str, Any],
    *,
    workspace_id: str = "laijuzhu",
    idempotency_key: str = "",
) -> Dict[str, Any]:
    edge_result = edge_result if isinstance(edge_result, dict) else {}
    provider_event = edge_result.get("provider_event") if isinstance(edge_result.get("provider_event"), dict) else {}
    provider = _clean_provider(provider_event.get("provider") or edge_result.get("provider"))
    provider_event_id = _clean_id(provider_event.get("provider_event_id") or provider_event.get("event_id"), 160)
    event_payload_hash = _clean_id(provider_event.get("provider_payload_hash"), 128)
    derived_idempotency = idempotency_key or "provider_edge:" + provider + ":" + (provider_event_id or event_payload_hash or _hash_text(json.dumps(provider_event, sort_keys=True))[:24])
    return {
        "workspace_id": _clean_id(workspace_id, 96) or "laijuzhu",
        "provider": provider,
        "provider_event_id": provider_event_id,
        "event_id": provider_event_id,
        "event_type": provider_event.get("event_type", ""),
        "status": provider_event.get("status", ""),
        "provider_status": provider_event.get("provider_status") or provider_event.get("status", ""),
        "amount": _to_int(provider_event.get("amount")),
        "currency": str(provider_event.get("currency") or "SGD").upper()[:12],
        "provider_ref": _clean_id(provider_event.get("provider_ref"), 160),
        "provider_payload_shape": provider_event.get("provider_payload_shape", ""),
        "provider_payload_hash": event_payload_hash,
        "provider_adapter_warnings": list(provider_event.get("provider_adapter_warnings") or []),
        "safe_provider_summary": provider_event.get("safe_provider_summary", {}),
        "source_family": PROVIDER_EVENT_SOURCE_FAMILY,
        "idempotency_key": _clean_id(derived_idempotency, 160),
        "adapter_evidence_only": True,
        "payment_execution_performed": False,
        "provider_truth_used": False,
        "raw_provider_payload_stored": False,
        "provider_edge": _edge_context(edge_result),
    }


def build_provider_event_handoff(
    edge_result: Dict[str, Any],
    *,
    intent_id: str,
    workspace_id: str = "laijuzhu",
    adapter_id: str = "",
    method: str = "POST",
    path: str = "",
    secret: str = "",
    idempotency_key: str = "",
) -> Dict[str, Any]:
    edge_result = edge_result if isinstance(edge_result, dict) else {}
    if edge_result.get("ok") is False:
        return _edge_error(str(edge_result.get("provider") or "payment_provider"), "provider_edge_failed", int(edge_result.get("status_code") or 400))
    if edge_result.get("status") != "provider_webhook_normalized":
        return _edge_error(
            str(edge_result.get("provider") or "payment_provider"),
            "provider_edge_not_ready_for_handoff",
            409,
            edge_status=edge_result.get("status", ""),
        )
    provider_event = edge_result.get("provider_event") if isinstance(edge_result.get("provider_event"), dict) else {}
    provider_status = str(provider_event.get("status") or provider_event.get("provider_status") or "")
    if provider_status == "requires_review":
        return _edge_error(str(edge_result.get("provider") or "payment_provider"), "provider_event_requires_review", 409)
    intent_id = _clean_id(intent_id, 120)
    if not intent_id:
        return _edge_error(str(edge_result.get("provider") or "payment_provider"), "intent_id_required", 400)

    provider = _clean_provider(provider_event.get("provider") or edge_result.get("provider"))
    target_path = path or f"/api/core/payments/intents/{intent_id}/provider-event"
    payload = provider_event_payload_from_edge(edge_result, workspace_id=workspace_id, idempotency_key=idempotency_key)
    adapter = _clean_id(adapter_id, 120) or f"{provider}-provider-edge"
    headers = adapter_signature.sign_adapter_headers(
        adapter_id=adapter,
        method=method,
        path=target_path,
        payload=payload,
        workspace_id=payload["workspace_id"],
        source_family=PROVIDER_EVENT_SOURCE_FAMILY,
        secret=secret,
    )
    if not headers.get(adapter_signature.ADAPTER_SIGNATURE_HEADER):
        return _edge_error(provider, "adapter_signature_secret_required", 500, adapter_id=adapter)
    return {
        "ok": True,
        "schema_version": HANDOFF_SCHEMA_VERSION,
        "phase": PHASE,
        "provider": provider,
        "status": "provider_edge_handoff_signed",
